/**
 * Packs the project into nakeeyat-ios-xcode.zip, ready to carry to a Mac.
 *
 *   npm run ios:bundle
 *
 * The npm script runs `ios:sync` first, so the archive always contains a fresh
 * build of the web app inside `ios/App/App/public`. That folder is what makes
 * the bundle worth having: it is gitignored, so a plain clone gives a Mac an
 * Xcode project that compiles to a white screen, whereas this zip opens and
 * runs with no Node and no npm install at the other end.
 *
 * Two things decide how this is written:
 *
 * 1. **It must not be built with PowerShell's `Compress-Archive`.** That is
 *    .NET's `ZipFile`, which writes entry names with backslashes. The ZIP spec
 *    forbids them and macOS reads them as literal filenames, so the whole tree
 *    arrives flattened into one directory of oddly-named files. The same trap
 *    is documented for `dist/` in the README. `tar -a` is libarchive on both
 *    Windows (bundled since Windows 10) and macOS, and always writes POSIX
 *    separators.
 * 2. **Nothing machine-specific may go in.** `android/local.properties` holds
 *    an absolute Windows path to the Android SDK, and on a Mac it produces the
 *    thoroughly misleading "The filename, directory name, or volume label
 *    syntax is incorrect". Gradle and Xcode both regenerate what they need.
 */
import { spawnSync } from 'node:child_process'
import { openSync, readSync, closeSync, statSync, rmSync } from 'node:fs'
import { join } from 'node:path'

const OUT = 'nakeeyat-ios-xcode.zip'

/**
 * Windows ships libarchive as System32\tar.exe, but Git Bash puts GNU tar
 * ahead of it on PATH -- and GNU tar cannot write a zip. Given `-a` and a
 * .zip name it quietly produces an uncompressed *tar* called .zip and exits 0,
 * which then fails much later on the Mac. Naming the binary avoids the whole
 * question of whose PATH this ran under.
 */
const TAR =
  process.platform === 'win32'
    ? join(process.env.SystemRoot ?? 'C:\\Windows', 'System32', 'tar.exe')
    : 'tar'

/** Everything the Mac needs, and nothing it does not. */
const INCLUDE = [
  'ios',
  'src',
  'public',
  'scripts',
  'android',
  'legacy',
  'index.html',
  'package.json',
  'package-lock.json',
  'tsconfig.json',
  'vite.config.ts',
  'capacitor.config.ts',
  'README.md',
  '.gitignore',
]

/**
 * Reinstalled by `npm install`, regenerated by the build, or specific to this
 * machine. `dist/` is left out because the copy that matters is already inside
 * `ios/App/App/public`, and shipping both would double the archive.
 */
const EXCLUDE = [
  'node_modules',
  '.git',
  '.idea',
  'dist',
  'screenshots',
  'audio-samples',
  'build',
  '*/build',
  '*/build/*',
  '.gradle',
  '*/.gradle',
  '*/.gradle/*',
  'local.properties',
  '*/local.properties',
  '*.apk',
  '*.zip',
  'tsconfig.tsbuildinfo',
  '*.iml',
]

const args = ['-a', '-c', '-f', OUT, ...EXCLUDE.map((p) => `--exclude=${p}`), ...INCLUDE]
const { status, error, stderr } = spawnSync(TAR, args, { encoding: 'utf8' })

if (error || status !== 0) {
  console.error(stderr || error?.message)
  console.error(`\nPacking failed. ${TAR} must be libarchive tar, which ships with Windows 10 and later and with macOS.`)
  process.exit(1)
}

/**
 * A zip starts "PK\x03\x04". Checking is not paranoia: the one way this script
 * has actually gone wrong was a tar written under a .zip name by a tar that
 * exited 0, and the symptom did not appear until someone opened it on a Mac.
 */
const fd = openSync(OUT, 'r')
const magic = Buffer.alloc(4)
readSync(fd, magic, 0, 4, 0)
closeSync(fd)

if (!magic.equals(Buffer.from([0x50, 0x4b, 0x03, 0x04]))) {
  rmSync(OUT)
  console.error(`${TAR} produced ${magic.toString('hex')} where a zip should start 504b0304 -- it is not`)
  console.error('libarchive tar. The bad archive has been deleted rather than left to fail on the Mac.')
  process.exit(1)
}

console.log(`  ${OUT}  ${(statSync(OUT).size / 1024 / 1024).toFixed(1)} MB`)
console.log('  Copy it to the Mac, unzip, and open ios/App/App.xcodeproj.')
